WITH enriched AS (SELECT e.*, p.salary AS employee_salary, p.level AS employee_level, p.email AS employee_email FROM employees e INNER JOIN employees p ON e.manager_id = p.id) SELECT s.id, s.email, s.manager_id, s.salary, s.hire_date, s.is_remote, s.level, s.employee_salary, s.employee_level, (SELECT MIN(t2.salary) FROM employees t2 WHERE t2.manager_id = s.manager_id) AS min_employee_salary FROM enriched s ORDER BY employee_salary DESC, id
